import{B as e,Q as t,s as n,z as r}from"./chunks/framework.DaWAnZmO.js";var i=JSON.parse(`{"title":"ADR-001 — Canonical Routing","description":"","frontmatter":{"title":"ADR-001 — Canonical Routing"},"headers":[],"relativePath":"architecture/adr-001.md","filePath":"architecture/adr-001.md"}`),a={name:`architecture/adr-001.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="adr-001-—-canonical-routing" tabindex="-1">ADR-001 — Canonical Routing <a class="header-anchor" href="#adr-001-—-canonical-routing" aria-label="Permalink to &quot;ADR-001 — Canonical Routing&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted (fork governance hard-stop in effect as of 2026-09-01).</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Multiple routing-related projects exist across the Phenotype org:</p><ul><li><strong>OmniRoute</strong> (this repo) — fork of <code>diegosouzapw/OmniRoute</code>, an OpenAI-compatible AI gateway with routing, load balancing, retries, and fallbacks</li><li><strong>phenoAI</strong> — Phenotype AI agent workspace and tooling</li><li><strong>phenoRouterMonitor</strong> — LLM router with Prometheus monitoring + tracing</li><li><strong>HeliosLab</strong> — internal research gateway for routing experiments</li></ul><p>The question: which one is canonical for production traffic?</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>OmniRoute is canonical</strong> for OpenAI-compatible gateway traffic.</p><p>Rationale:</p><ul><li>Single-binary deploy</li><li>SQLite default store (no external DB)</li><li>Plugin manifest is mature and provider-agnostic</li><li><code>PerSpecDecision</code> hooks for governance interception</li><li>Local-first: runs on Apple Silicon and Raspberry Pi</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>phenoAI</code> MUST route through OmniRoute for all OpenAI-compatible calls</li><li><code>phenoRouterMonitor</code> continues to be a Prometheus exporter — it MAY sit beside OmniRoute, but it MUST NOT replace it</li><li><code>HeliosLab</code> continues as a research branch; production traffic stays on OmniRoute</li></ul><h2 id="supersedes" tabindex="-1">Supersedes <a class="header-anchor" href="#supersedes" aria-label="Permalink to &quot;Supersedes&quot;">​</a></h2><p>None.</p><h2 id="referenced-by" tabindex="-1">Referenced by <a class="header-anchor" href="#referenced-by" aria-label="Permalink to &quot;Referenced by&quot;">​</a></h2><ul><li><code>docs/OKR.md</code></li><li><code>docs/PERF_BUDGETS.md</code></li><li><code>docs/INCIDENT_RESPONSE.md</code></li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};